148:     /// Traverses the call graph starting from the given root. For every function, we visit all
149:     /// instruction looking for the items that should be included in the compilation.
150:     fn reachable_items(&mut self) {
151:         while let Some(to_visit) = self.queue.pop() {
152:             if !self.collected.contains(&to_visit) {
153:                 self.collected.insert(to_visit.clone());
154:                 let next_items = match &to_visit {
155:                     MonoItem::Fn(instance) => self.visit_fn(*instance),
156:                     MonoItem::Static(static_def) => self.visit_static(*static_def),
157:                     MonoItem::GlobalAsm(_) => {
158:                         self.visit_asm(&to_visit);
159:                         vec![]
160:                     }
161:                 };
162:                 self.call_graph.add_edges(to_visit, &next_items);
163: 
164:                 self.queue.extend(next_items.into_iter().filter_map(
165:                     |CollectedItem { item, .. }| (!self.collected.contains(&item)).then_some(item),
166:                 ));
167:             }
168:         }
169:     }
