171:     /// Visit a function and collect all mono-items reachable from its instructions.
172:     fn visit_fn(&mut self, instance: Instance) -> Vec<CollectedItem> {
173:         let _guard = debug_span!("visit_fn", function=?instance).entered();
174:         let body = self.transformer.body_ref(self.tcx, instance);
175:         let mut collector =
176:             MonoItemsFnCollector { tcx: self.tcx, collected: FxHashSet::default(), body };
177:         collector.visit_body(body);
178:         collector.collected.into_iter().collect()
179:     }
