314:     // Avoid printing the same error multiple times for different instantiations of the same item.
315:     let mut def_ids = HashSet::new();
316:     let reachable_functions: HashSet<DefId> = items
317:         .iter()
318:         .filter_map(|i| match i {
319:             MonoItem::Fn(instance) => Some(instance.def.def_id()),
320:             _ => None,
321:         })
322:         .collect();
323:     for item in items.iter().filter(|i| matches!(i, MonoItem::Fn(..) | MonoItem::Static(..))) {
324:         let def_id = match item {
325:             MonoItem::Fn(instance) => instance.def.def_id(),
326:             MonoItem::Static(def) => def.def_id(),
327:             MonoItem::GlobalAsm(_) => {
328:                 unreachable!()
329:             }
330:         };
331:         if !def_ids.contains(&def_id) {
332:             let attributes = KaniAttributes::for_def_id(tcx, def_id);
