334:             attributes.check_unstable_features(&queries.args().unstable_features);
335:             // Check whether all `proof_for_contract` targets are reachable
336:             attributes.check_proof_for_contract_reachability(&reachable_functions);
337:             def_ids.insert(def_id);
338:         }
339:     }
340:     tcx.dcx().abort_if_errors();
